-- ---------------------------------------------------------------------
-- VERIFY (read the output — do not skip). Expected: 211 loaded,
-- 0 unresolved customer links, 29 distinct customers linked.
-- ---------------------------------------------------------------------
select
  (select count(*) from public.archive_photos)                                  as total_rows,
  (select count(*) from public.archive_photos where status = 'pending')         as pending,
  (select count(*) from public.archive_photos where status = 'excluded')        as excluded,
  (select count(distinct resolved_customer_id) from public.archive_photos
     where resolved_customer_id is not null)                                    as customers_linked,
  (select count(*) from public.archive_photos
     where resolved_customer_ref is not null and resolved_customer_id is null)  as unresolved_links,
  (select count(distinct resolved_address_key) from public.archive_photos
     where resolved_address_key is not null)                                    as distinct_properties;

-- Any row listed here had a customer prefix that no longer resolves — re-link
-- it by hand (resolved_name says who it should be). Empty result = all good.
select drive_file_id, original_title, resolved_name, resolved_customer_ref
from public.archive_photos
where resolved_customer_ref is not null and resolved_customer_id is null
order by original_title;
